import React from 'react';
import { Card, Form, Input, DatePicker, Select } from 'antd';
import SourcesExcludedInput from './SourcesExcludedInput';
import './styles/NormalRouteBuilder.css';

const { RangePicker } = DatePicker;

const NormalRouteBuilder = ({ onSearch, isLoading, errors }) => {
  const [form] = Form.useForm();

  const handleSubmit = (values) => {
    const { path, sourcesExcluded, dateRange } = values;
    onSearch({
      path,
      sourcesExcluded,
      dateRange,
      apiKey: localStorage.getItem('apiKey')
    });
  };

  return (
    <Card className="normal-route-builder">
      <Form
        form={form}
        layout="vertical"
        onFinish={handleSubmit}
        initialValues={{
          sourcesExcluded: []
        }}
      >
        <Form.Item
          label="Path"
          name="path"
          validateStatus={errors.path ? 'error' : ''}
          help={errors.path}
          rules={[{ required: true, message: 'Please enter a path' }]}
        >
          <Input placeholder="Enter path (e.g., YYZ-LHR)" />
        </Form.Item>

        <Form.Item
          label="Sources Excluded"
          name="sourcesExcluded"
        >
          <SourcesExcludedInput />
        </Form.Item>

        <Form.Item
          label="Date Range"
          name="dateRange"
        >
          <RangePicker />
        </Form.Item>

        <Form.Item>
          <button
            type="submit"
            className="ant-btn ant-btn-primary"
            disabled={isLoading}
          >
            {isLoading ? 'Searching...' : 'Search'}
          </button>
        </Form.Item>
      </Form>
    </Card>
  );
};

export default NormalRouteBuilder;
